#include <iostream>
#include <algorithm>
#include <map>

int main() {
    int a, b;
    std::cin >> a >> b;
    int x = std::min(a, b);
    int y = std::max(a, b);
    int adjustment = 0;

    if (x == 1) {
        adjustment = std::min(y % 6, 6 - y % 6);
    } else if (x == 2) {
        std::map<int, int> m = {{2, 4}, {3, 2}, {7, 2}};
        auto it = m.find(y);
        if (it != m.end()) {
            adjustment = it->second;
        } else {
            adjustment = 0;
        }
    } else {
        adjustment = (x & 1) * (y & 1);
    }

    std::cout << x * y - adjustment << std::endl;
    return 0;
}
